using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using PersonalOrderDesk.Client;
using PersonalOrderDesk.Data;
using PersonalOrderDesk.Domain;
using PersonalOrderDesk.Services;

namespace PersonalOrderDesk.Tests;
public sealed class ThreeWaySyncTests : IAsyncLifetime
{
    private readonly string root=Path.Combine(Path.GetTempPath(),"Desk-merge-"+Guid.NewGuid().ToString("N"));
    private ServiceProvider pc=null!,phone=null!;private Guid id;private SyncData baseline=null!;
    private string Pc=>Path.Combine(root,"pc.db");private string Phone=>Path.Combine(root,"phone.db");
    private readonly DateOnly today=DateOnly.FromDateTime(DateTime.Today);
    public async Task InitializeAsync(){Directory.CreateDirectory(root);pc=new ServiceCollection().AddLocalWorkspace(Pc).BuildServiceProvider();await using(var scope=pc.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<DeskDbContext>().Database.MigrateAsync();var item=await P.SaveOrder(null,new(null,"SYNC-001","同步测试",ProjectType.Simulation,null,null,today,DueDateMode.Auto,null,"初始进度","初始下一步",70000,null,null));id=item.WorkItem.Id!.Value;await using(var source=new SqliteConnection($"Data Source={Pc};Pooling=False"))await using(var target=new SqliteConnection($"Data Source={Phone};Pooling=False")){await source.OpenAsync();await target.OpenAsync();source.BackupDatabase(target);}baseline=await ThreeWaySync.Read(Pc);phone=new ServiceCollection().AddLocalWorkspace(Phone).BuildServiceProvider();}
    private IWorkspaceGateway P=>pc.GetRequiredService<IWorkspaceGateway>();private IWorkspaceGateway M=>phone.GetRequiredService<IWorkspaceGateway>();
    public async Task DisposeAsync(){await pc.DisposeAsync();await phone.DisposeAsync();Directory.Delete(root,true);}
    private async Task<SyncMergeResult> Merge(Dictionary<string,string>? choices=null)=>ThreeWaySync.Merge(baseline,await ThreeWaySync.Read(Pc),await ThreeWaySync.Read(Phone),choices);
    private async Task Apply(SyncMergeResult merge)=>await ThreeWaySync.Apply(Pc,ThreeWaySync.Fingerprint(await ThreeWaySync.Read(Pc)),merge.Data,today);
    [Fact]public async Task Separate_fields_merge_and_repeated_sync_does_not_duplicate(){var p=await P.Editor(id);await P.Progress(id,new(p.Version,"电脑进度",p.NextStep,p.ProjectPath));var m=await M.Editor(id);await M.Progress(id,new(m.Version,m.CurrentWork,"手机下一步",m.ProjectPath));var merge=await Merge();Assert.Empty(merge.Conflicts);await Apply(merge);var result=await P.Editor(id);Assert.Equal("电脑进度",result.CurrentWork);Assert.Equal("手机下一步",result.NextStep);var repeated=await Merge();Assert.Empty(repeated.Conflicts);var count=(await ThreeWaySync.Read(Pc)).Tables["ActivityLogs"].Rows.Count;await Apply(repeated);Assert.Equal(count,(await ThreeWaySync.Read(Pc)).Tables["ActivityLogs"].Rows.Count);}
    [Fact]public async Task Same_field_requires_choice_and_keeps_other_pc_changes(){var p=await P.Editor(id);await P.Progress(id,new(p.Version,"电脑进度","电脑后续",null));var m=await M.Editor(id);await M.Progress(id,new(m.Version,"手机进度",m.NextStep,null));var review=await Merge();var conflict=Assert.Single(review.Conflicts);Assert.Equal("当前进度",conflict.Field);var chosen=await Merge(new(){[conflict.Id]="phone"});await Apply(chosen);var result=await P.Editor(id);Assert.Equal("手机进度",result.CurrentWork);Assert.Equal("电脑后续",result.NextStep);}
    [Fact]public async Task New_phone_order_receipt_expense_and_additional_relation_keep_ids(){var child=await M.AddWork(id,new(null,"SYNC-001","手机追加",ProjectType.Simulation,null,null,today,DueDateMode.Auto,null,null,null,10000,null,null));var childId=child.WorkItem.Id!.Value;await M.Payment(new(TransactionType.Receipt,5000,null,DateKnowledge.Unknown,"微信",null,null,"merge-receipt",[new(childId,5000)]));await M.Expense(childId,new((await M.Editor(childId)).Version,2000,null,"材料",null));var merge=await Merge();Assert.Empty(merge.Conflicts);await Apply(merge);Assert.Equal("手机追加",(await P.Editor(childId)).ProjectName);var money=(await P.Order(childId)).Money;Assert.Equal(5000,money.NetReceivedCents);Assert.Equal(2000,money.TotalCostCents);Assert.Single((await P.Order(id)).Detail.Relations);await Apply(await Merge());Assert.Single((await P.Order(childId)).Money.Transactions);}
    [Fact]public async Task Independent_receipts_on_both_devices_survive_merge(){await P.Payment(new(TransactionType.Receipt,10000,null,DateKnowledge.Unknown,"微信",null,null,"pc-payment",[new(id,10000)]));await M.Payment(new(TransactionType.Receipt,20000,null,DateKnowledge.Unknown,"支付宝",null,null,"phone-payment",[new(id,20000)]));var merge=await Merge();Assert.Empty(merge.Conflicts);await Apply(merge);Assert.Equal(30000,(await P.Order(id)).Money.NetReceivedCents);}
    [Fact]public async Task Combined_over_refund_rolls_back_every_change(){await P.Payment(new(TransactionType.Receipt,30000,null,DateKnowledge.Unknown,"微信",null,null,"shared-base",[new(id,30000)]));await pc.DisposeAsync();await phone.DisposeAsync();File.Delete(Phone);await using(var source=new SqliteConnection($"Data Source={Pc};Pooling=False"))await using(var target=new SqliteConnection($"Data Source={Phone};Pooling=False")){await source.OpenAsync();await target.OpenAsync();source.BackupDatabase(target);}baseline=await ThreeWaySync.Read(Pc);pc=new ServiceCollection().AddLocalWorkspace(Pc).BuildServiceProvider();phone=new ServiceCollection().AddLocalWorkspace(Phone).BuildServiceProvider();await P.Payment(new(TransactionType.Refund,20000,null,DateKnowledge.Unknown,"微信",null,null,"pc-refund",[new(id,20000)]));await M.Payment(new(TransactionType.Refund,20000,null,DateKnowledge.Unknown,"微信",null,null,"phone-refund",[new(id,20000)]));var before=ThreeWaySync.Fingerprint(await ThreeWaySync.Read(Pc));await Assert.ThrowsAsync<InvalidDataException>(()=>Apply(Merge().GetAwaiter().GetResult()));Assert.Equal(before,ThreeWaySync.Fingerprint(await ThreeWaySync.Read(Pc)));Assert.Equal(10000,(await P.Order(id)).Money.NetReceivedCents);}
    [Fact]public async Task Stale_preview_cannot_overwrite_newer_pc_data(){var merge=await Merge();var before=ThreeWaySync.Fingerprint(await ThreeWaySync.Read(Pc));await P.Progress(id,new((await P.Editor(id)).Version,"预览后改动",null,null));await Assert.ThrowsAsync<InvalidOperationException>(()=>ThreeWaySync.Apply(Pc,before,merge.Data,today));Assert.Equal("预览后改动",(await P.Editor(id)).CurrentWork);}
    [Fact]public async Task Deleted_order_retains_history_and_money_after_merge(){await M.Payment(new(TransactionType.Receipt,10000,null,DateKnowledge.Unknown,"微信",null,null,"phone-before-delete",[new(id,10000)]));await M.Delete(id,(await M.Editor(id)).Version);await Apply(await Merge());Assert.Empty((await P.State()).Orders);var recycled=Assert.Single((await P.State()).Recycle);await P.Restore(id,recycled.Version);Assert.Equal(10000,(await P.Order(id)).Money.NetReceivedCents);}
    [Fact]public async Task Altered_provenance_or_direct_deletion_is_rejected(){var data=await ThreeWaySync.Read(Phone);data.Tables["WorkItems"].Rows[id.ToString().ToUpperInvariant()]["SourceKind"]="HistoricalImport";Assert.Throws<InvalidDataException>(()=>ThreeWaySync.Merge(baseline,baseline,data));data=await ThreeWaySync.Read(Phone);data.Tables["WorkItems"].Rows.Clear();Assert.Throws<InvalidDataException>(()=>ThreeWaySync.Merge(baseline,baseline,data));}
}
